<script lang="ts">import { goto } from '$app/navigation'; import { onMount } from 'svelte'; import { auth } from '$lib/stores/auth.svelte'; import Button from './ui/Button.svelte'; onMount(() => auth.restore()); async function signOut() { await auth.logout(); goto('/'); }</script>
<header class="border-b bg-white"><nav class="mx-auto flex max-w-6xl items-center gap-4 px-4 py-3 sm:px-6"><a href="/" class="mr-auto font-semibold text-cyan-900">Booking System</a><a href="/bookings" class="text-sm hover:text-cyan-800">My bookings</a>{#if auth.isAdmin}<a href="/admin" class="text-sm hover:text-cyan-800">Admin</a>{/if}{#if !auth.ready}<span class="text-sm text-slate-500">Loading session…</span>{:else if auth.user}<span class="hidden text-sm text-slate-600 sm:inline">{auth.user.name}</span><Button variant="outline" onclick={signOut}>Log out</Button>{:else}<a href="/login" class="text-sm hover:text-cyan-800">Log in</a><Button onclick={() => goto('/register')}>Register</Button>{/if}</nav></header>
